-- Deterministic phone catalog seed.
--
-- Idempotent: re-running this file updates the same rows and never creates
-- duplicates. Run it after all migrations with `make seed`.

BEGIN;

-- Keep the original catalog rows for rollback compatibility, but hide them
-- from the phone catalog.
UPDATE products
SET active = false
WHERE id IN (
    '00000000-0000-0001-0000-000000000001',
    '00000000-0000-0001-0000-000000000002',
    '00000000-0000-0001-0000-000000000003',
    '00000000-0000-0001-0000-000000000004',
    '00000000-0000-0001-0000-000000000005',
    '00000000-0000-0001-0000-000000000006',
    '00000000-0000-0001-0000-000000000007',
    '00000000-0000-0001-0000-000000000008',
    '00000000-0000-0001-0000-000000000009'
);

-- Converge child rows from older versions of this seed without touching
-- generic catalog data or rows outside the reserved deterministic namespaces.
-- Cart-referenced variants are retained and deactivated below instead of
-- being deleted, because cart_items.variant_id uses ON DELETE RESTRICT.
DELETE FROM variant_option_values
WHERE variant_id::text LIKE '13000000-%'
  AND variant_id NOT IN (
      '13000000-0000-0000-0000-000000000001',
      '13000000-0000-0000-0000-000000000002',
      '13000000-0000-0000-0000-000000000003',
      '13000000-0000-0000-0000-000000000004',
      '13000000-0000-0000-0000-000000000005',
      '13000000-0000-0000-0000-000000000006',
      '13000000-0000-0000-0000-000000000007',
      '13000000-0000-0000-0000-000000000008',
      '13000000-0000-0000-0000-000000000009',
      '13000000-0000-0000-0000-000000000010',
      '13000000-0000-0000-0000-000000000011',
      '13000000-0000-0000-0000-000000000012'
  )
  AND NOT EXISTS (
      SELECT 1 FROM cart_items
      WHERE cart_items.variant_id = variant_option_values.variant_id
  );
DELETE FROM variant_option_values
WHERE variant_id IN (
    '13000000-0000-0000-0000-000000000001',
    '13000000-0000-0000-0000-000000000002',
    '13000000-0000-0000-0000-000000000003',
    '13000000-0000-0000-0000-000000000004',
    '13000000-0000-0000-0000-000000000005',
    '13000000-0000-0000-0000-000000000006',
    '13000000-0000-0000-0000-000000000007',
    '13000000-0000-0000-0000-000000000008',
    '13000000-0000-0000-0000-000000000009',
    '13000000-0000-0000-0000-000000000010',
    '13000000-0000-0000-0000-000000000011',
    '13000000-0000-0000-0000-000000000012'
);
DELETE FROM product_variants
WHERE id::text LIKE '13000000-%'
  AND NOT EXISTS (
      SELECT 1 FROM cart_items
      WHERE cart_items.variant_id = product_variants.id
  );
UPDATE product_variants
SET active = false,
    updated_at = now()
WHERE id::text LIKE '13000000-%'
  AND id NOT IN (
      '13000000-0000-0000-0000-000000000001',
      '13000000-0000-0000-0000-000000000002',
      '13000000-0000-0000-0000-000000000003',
      '13000000-0000-0000-0000-000000000004',
      '13000000-0000-0000-0000-000000000005',
      '13000000-0000-0000-0000-000000000006',
      '13000000-0000-0000-0000-000000000007',
      '13000000-0000-0000-0000-000000000008',
      '13000000-0000-0000-0000-000000000009',
      '13000000-0000-0000-0000-000000000010',
      '13000000-0000-0000-0000-000000000011',
      '13000000-0000-0000-0000-000000000012'
  );
DELETE FROM product_option_values
WHERE id::text LIKE '12000000-%'
  AND NOT EXISTS (
      SELECT 1 FROM variant_option_values
      WHERE variant_option_values.option_value_id = product_option_values.id
  );
DELETE FROM product_option_groups
WHERE id::text LIKE '11000000-%'
  AND NOT EXISTS (
      SELECT 1 FROM variant_option_values
      WHERE variant_option_values.group_id = product_option_groups.id
  );
DELETE FROM product_images
WHERE id::text LIKE '10000000-0000-0002-%';

INSERT INTO categories (id, name) VALUES
    ('00000000-0000-0000-0000-000000000001', 'Electronics'),
    ('00000000-0000-0000-0000-000000000002', 'Books'),
    ('00000000-0000-0000-0000-000000000003', 'Clothing'),
    ('00000000-0000-0000-0000-000000000004', 'Home & Kitchen'),
    ('10000000-0000-0000-0000-000000000001', 'Apple'),
